# fifo_agent.py implements pure FIFO scheduling (no carbon awareness).
# === BEGIN CARBON-AWARE LOGIC ===
import numpy as np
from agents.agent import Agent
import heapq


class NewAgent(Agent):
    def __init__(self, exec_cap, carbon_schedule, exec_lower_bound=20):
        Agent.__init__(self)
        self.exec_map = {}
        self.carbon_schedule = carbon_schedule
        self.exec_cap_MAX = exec_cap
        self.exec_cap = exec_cap
        self.B = exec_lower_bound
        self.max_carbon_intensity = max(self.carbon_schedule.values()) if self.carbon_schedule else 1.0

    def get_carbon_intensity(self, current_time):
        current_carbon = self.carbon_schedule.get(current_time, 0.0)
        L = 0.0
        U = self.max_carbon_intensity * 1.1
        if U <= L:
            U = L + 1.0
        return (current_carbon, L, U)

    def _compute_dynamic_budget(self, current_time):
        current_carbon, L, U = self.get_carbon_intensity(current_time)
        normalized_ci = (current_carbon - L) / (U - L) if (U - L) > 0 else 0.0
        carbon_factor = max(0.1, 1.0 - normalized_ci)
        B_soft = int(self.exec_cap_MAX * carbon_factor)
        B_soft = max(self.B, min(self.exec_cap_MAX, B_soft))
        return B_soft, current_carbon

    def _estimate_criticality(self, job_dag, frontier_nodes):
        critical_nodes = []
        for node in frontier_nodes:
            if node.job_dag != job_dag:
                continue
            remaining_work = node.num_tasks - node.next_task_idx
            for child in node.children:
                remaining_work += child.num_tasks
            critical_nodes.append((remaining_work, node))
        if critical_nodes:
            critical_nodes.sort(reverse=True)
            return critical_nodes[0][1]
        return None

    def get_action(self, obs):
        job_dags, source_job, num_source_exec, frontier_nodes, executor_limits, exec_commit, moving_executors, action_map, current_time = obs

        for job_dag in job_dags:
            if job_dag not in self.exec_map:
                self.exec_map[job_dag] = 0
        for job_dag in list(self.exec_map):
            if job_dag not in job_dags:
                del self.exec_map[job_dag]

        total_exec_in_use = sum(self.exec_map.values())
        B_soft, current_carbon = self._compute_dynamic_budget(current_time)

        carbon_aware_flag = False
        if total_exec_in_use >= B_soft:
            carbon_aware_flag = True
            if total_exec_in_use >= self.exec_cap_MAX:
                if source_job is not None and source_job in self.exec_map:
                    self.exec_map[source_job] = max(self.exec_map[source_job] - num_source_exec, 0)
                return None, num_source_exec, carbon_aware_flag

        if num_source_exec <= 0:
            return None, 0, carbon_aware_flag

        critical_tasks = []
        non_critical_tasks = []
        for job_dag in job_dags:
            crit_node = self._estimate_criticality(job_dag, frontier_nodes)
            if crit_node:
                critical_tasks.append((job_dag, crit_node))
            else:
                for node in frontier_nodes:
                    if node.job_dag == job_dag:
                        non_critical_tasks.append((job_dag, node))
                        break

        if total_exec_in_use < B_soft:
            for job_dag, node in critical_tasks:
                if self.exec_map[job_dag] < self.exec_cap_MAX:
                    use_exec = min(
                        node.num_tasks - node.next_task_idx - exec_commit.node_commit[node] - moving_executors.count(node),
                        num_source_exec,
                        self.exec_cap_MAX - self.exec_map[job_dag]
                    )
                    if use_exec > 0:
                        self.exec_map[job_dag] += use_exec
                        return node, use_exec, carbon_aware_flag

            for job_dag, node in non_critical_tasks:
                if self.exec_map[job_dag] < self.exec_cap_MAX:
                    use_exec = min(
                        node.num_tasks - node.next_task_idx - exec_commit.node_commit[node] - moving_executors.count(node),
                        num_source_exec,
                        self.exec_cap_MAX - self.exec_map[job_dag]
                    )
                    if use_exec > 0:
                        self.exec_map[job_dag] += use_exec
                        return node, use_exec, carbon_aware_flag

        if source_job is not None:
            for node in frontier_nodes:
                if node.job_dag == source_job:
                    use_exec = min(
                        node.num_tasks - node.next_task_idx - exec_commit.node_commit[node] - moving_executors.count(node),
                        num_source_exec
                    )
                    if use_exec > 0:
                        self.exec_map[source_job] += use_exec
                        return node, use_exec, carbon_aware_flag

        return None, num_source_exec, carbon_aware_flag
# === END CARBON-AWARE LOGIC ===

