import numpy as np
from agents.agent import Agent
import math


class NewAgent(Agent):
    def __init__(self, exec_cap, carbon_schedule, exec_lower_bound=20):
        Agent.__init__(self)
        self.exec_map = {}
        self.carbon_schedule = carbon_schedule
        self.exec_cap_MAX = exec_cap
        self.exec_cap = exec_cap
        self.B = exec_lower_bound
        self.last_carbon_update = 0
        self.update_interval = 30000
        self.carbon_threshold_low = 280
        self.carbon_threshold_high = 400
        self.burst_multiplier = 2.0
        self.throttle_multiplier = 0.5

    def get_carbon_intensity(self, current_time):
        current_carbon = self.carbon_schedule.get(current_time, 300)
        L = self.carbon_threshold_low
        U = self.carbon_threshold_high
        return current_carbon, L, U

    def _update_dynamic_cap(self, current_time):
        if current_time - self.last_carbon_update < self.update_interval:
            return
        self.last_carbon_update = current_time
        current_carbon, L, U = self.get_carbon_intensity(current_time)
        if current_carbon <= L:
            self.exec_cap = min(self.exec_cap_MAX, int(self.exec_cap_MAX * self.burst_multiplier))
        elif current_carbon >= U:
            self.exec_cap = max(self.B, int(self.exec_cap_MAX * self.throttle_multiplier))
        else:
            self.exec_cap = self.exec_cap_MAX
        self.exec_cap = max(self.B, min(self.exec_cap_MAX, self.exec_cap))

    def _compute_critical_path_heuristic(self, job_dag):
        remaining_nodes = [n for n in job_dag.nodes if not n.completed]
        if not remaining_nodes:
            return 0
        max_depth = 0
        for node in remaining_nodes:
            depth = 0
            current = node
            while current and not current.completed:
                depth += 1
                children = [c for c in current.children if not c.completed]
                if not children:
                    break
                current = children[0]
            max_depth = max(max_depth, depth)
        return max_depth

    def get_action(self, obs):
        job_dags, source_job, num_source_exec, frontier_nodes, executor_limits, exec_commit, moving_executors, action_map, current_time = obs

        for job_dag in job_dags:
            if job_dag not in self.exec_map:
                self.exec_map[job_dag] = 0
        for job_dag in list(self.exec_map):
            if job_dag not in job_dags:
                del self.exec_map[job_dag]

        self._update_dynamic_cap(current_time)

        num_exec = 0
        for job_dag in list(self.exec_map):
            num_exec += self.exec_map[job_dag]

        current_carbon, L, U = self.get_carbon_intensity(current_time)
        carbon_aware_pause = (source_job is not None and current_carbon >= U)

        if num_exec >= self.exec_cap or carbon_aware_pause:
            if source_job is not None and source_job in list(self.exec_map):
                self.exec_map[source_job] = max(self.exec_map[source_job] - num_source_exec, 0)
            return None, num_source_exec, True

        if source_job is not None:
            for node in source_job.frontier_nodes:
                if node in frontier_nodes:
                    return node, num_source_exec, False
            for node in frontier_nodes:
                if node.job_dag == source_job:
                    return node, num_source_exec, False

        job_priority_list = []
        for job_dag in job_dags:
            if self.exec_map[job_dag] < self.exec_cap:
                cp_length = self._compute_critical_path_heuristic(job_dag)
                job_priority_list.append((cp_length, job_dag))
        job_priority_list.sort(key=lambda x: x[0], reverse=True)

        for _, job_dag in job_priority_list:
            next_node = None
            for node in job_dag.frontier_nodes:
                if node in frontier_nodes:
                    next_node = node
                    break
            if next_node is None:
                for node in frontier_nodes:
                    if node.job_dag == job_dag:
                        next_node = node
                        break
            if next_node is not None:
                use_exec = min(
                    next_node.num_tasks - next_node.next_task_idx - exec_commit.node_commit[next_node] - moving_executors.count(next_node),
                    num_source_exec,
                    self.exec_cap - self.exec_map[job_dag]
                )
                if use_exec > 0:
                    self.exec_map[job_dag] += use_exec
                    carbon_aware_flag = (current_carbon >= U)
                    return next_node, use_exec, carbon_aware_flag

        return None, num_source_exec, False
# === END CARBON-AWARE LOGIC ===

