import numpy as np
from agents.agent import Agent
import math


class NewAgent(Agent):
    def __init__(self, exec_cap, carbon_schedule, exec_lower_bound=20):
        Agent.__init__(self)
        self.exec_map = {}
        self.carbon_schedule = carbon_schedule
        self.exec_cap_MAX = exec_cap
        self.exec_cap = exec_cap
        self.B = exec_lower_bound
        self.lookahead_window_ms = 30 * 60 * 1000
        self.carbon_threshold = None
        self._init_threshold()

    def _init_threshold(self):
        if self.carbon_schedule:
            intensities = list(self.carbon_schedule.values())
            self.carbon_threshold = np.median(intensities)
        else:
            self.carbon_threshold = 300

    def get_carbon_intensity(self, current_time):
        current_carbon = self.carbon_schedule.get(current_time, float('inf'))
        future_times = [t for t in self.carbon_schedule.keys() if current_time <= t <= current_time + self.lookahead_window_ms]
        future_carbons = [self.carbon_schedule[t] for t in future_times if t in self.carbon_schedule]
        avg_future = np.mean(future_carbons) if future_carbons else current_carbon
        L = min(current_carbon, avg_future) * 0.8
        U = max(current_carbon, avg_future) * 1.2
        if L >= U:
            U = L + 1
        return current_carbon, L, U

    def _calculate_effective_cap(self, current_time):
        current_carbon, L, U = self.get_carbon_intensity(current_time)
        C_decision = max(current_carbon, (L + U) / 2)
        if C_decision > self.carbon_threshold:
            effective_cap = self.B + int(0.1 * (self.exec_cap_MAX - self.B))
        else:
            effective_cap = self.exec_cap_MAX
        effective_cap = max(self.B, min(effective_cap, self.exec_cap_MAX))
        return effective_cap, C_decision > self.carbon_threshold

    def get_action(self, obs):
        job_dags, source_job, num_source_exec, frontier_nodes, executor_limits, exec_commit, moving_executors, action_map, current_time = obs

        for job_dag in job_dags:
            if job_dag not in self.exec_map:
                self.exec_map[job_dag] = 0
        for job_dag in list(self.exec_map):
            if job_dag not in job_dags:
                del self.exec_map[job_dag]

        num_exec = sum(self.exec_map[job_dag] for job_dag in self.exec_map)
        effective_cap, is_high_carbon = self._calculate_effective_cap(current_time)

        if num_exec >= effective_cap:
            if source_job is not None and source_job in self.exec_map:
                self.exec_map[source_job] = max(self.exec_map[source_job] - num_source_exec, 0)
            return None, num_source_exec, is_high_carbon

        if source_job is not None:
            for node in frontier_nodes:
                if node.job_dag == source_job:
                    return node, num_source_exec, is_high_carbon

        for job_dag in job_dags:
            if self.exec_map[job_dag] < effective_cap:
                for node in frontier_nodes:
                    if node.job_dag == job_dag:
                        use_exec = min(
                            node.num_tasks - node.next_task_idx - exec_commit.node_commit[node] - moving_executors.count(node),
                            num_source_exec,
                            effective_cap - self.exec_map[job_dag]
                        )
                        if use_exec > 0:
                            self.exec_map[job_dag] += use_exec
                            return node, use_exec, is_high_carbon

        return None, num_source_exec, is_high_carbon
# === END CARBON-AWARE LOGIC ===

