import numpy as np
from agents.agent import Agent
import heapq
from collections import defaultdict, deque


class NewAgent(Agent):
    def __init__(self, exec_cap, carbon_schedule, exec_lower_bound=20):
        Agent.__init__(self)
        self.exec_map = {}
        self.carbon_schedule = carbon_schedule
        self.exec_cap_MAX = exec_cap
        self.exec_cap = exec_cap
        self.B = exec_lower_bound

        self.carbon_forecast = {}
        self.last_forecast_time = -float('inf')
        self.forecast_horizon = 300000
        self.forecast_interval = 50000

        self.job_slack = {}
        self.job_carbon_budget = {}
        self.job_remaining_work = {}

        self.carbon_history = []
        self.history_window = 10

        self.low_window_threshold = 280
        self.high_window_threshold = 400

    def get_carbon_intensity(self, current_time):
        current_carbon = self.carbon_schedule.get(current_time, 300)
        L = self.low_window_threshold
        U = self.high_window_threshold
        return current_carbon, L, U

    def _update_carbon_forecast(self, current_time):
        if current_time - self.last_forecast_time < self.forecast_interval:
            return

        self.last_forecast_time = current_time
        self.carbon_forecast.clear()

        times = []
        carbons = []
        for t in range(current_time, current_time + self.forecast_horizon + 1, 10000):
            c = self.carbon_schedule.get(t, 300)
            times.append(t)
            carbons.append(c)

        if len(carbons) < 2:
            return

        window_size = 3
        ma = []
        for i in range(len(carbons)):
            start = max(0, i - window_size + 1)
            ma.append(np.mean(carbons[start:i+1]))

        gradient = np.gradient(ma)

        low_windows = []
        in_window = False
        window_start = 0
        for i, (t, c, m) in enumerate(zip(times, carbons, ma)):
            if c < self.low_window_threshold and m < self.low_window_threshold:
                if not in_window:
                    in_window = True
                    window_start = t
            else:
                if in_window:
                    low_windows.append((window_start, t))
                    in_window = False
        if in_window:
            low_windows.append((window_start, times[-1]))

        next_low_window = None
        for start, end in low_windows:
            if start > current_time:
                next_low_window = (start, end)
                break

        for i, t in enumerate(times):
            if i >= len(gradient):
                continue
            score = 0.0
            if carbons[i] < self.low_window_threshold:
                score = -2.0
            elif carbons[i] > self.high_window_threshold:
                score = 2.0
            else:
                score = (carbons[i] - 300) / 100

            if next_low_window:
                dist_to_start = max(0, next_low_window[0] - t) / 100000.0
                if t >= next_low_window[0] and t <= next_low_window[1]:
                    score -= 3.0
                elif t < next_low_window[0]:
                    score -= 1.0 / (1.0 + dist_to_start)

            self.carbon_forecast[t] = {
                'carbon': carbons[i],
                'score': score,
                'gradient': gradient[i],
                'in_low_window': carbons[i] < self.low_window_threshold
            }

    def _compute_job_metrics(self, job_dag, frontier_nodes):
        if job_dag not in self.job_remaining_work:
            total_tasks = 0
            for node in job_dag.nodes:
                total_tasks += node.num_tasks
            self.job_remaining_work[job_dag] = total_tasks

        remaining = 0
        for node in job_dag.nodes:
            remaining += node.num_tasks - node.next_task_idx

        if job_dag not in self.job_slack:
            self.job_slack[job_dag] = {}
            for node in job_dag.nodes:
                est = 0
                lst = float('inf')
                self.job_slack[job_dag][node] = max(0, lst - est)

        if job_dag not in self.job_carbon_budget:
            avg_low_carbon = 250
            self.job_carbon_budget[job_dag] = remaining * avg_low_carbon

        critical_path_ratio = 0.0
        for node in frontier_nodes:
            if node.job_dag == job_dag:
                if self.job_slack[job_dag].get(node, 1) == 0:
                    critical_path_ratio = 1.0
                    break

        return remaining, self.job_carbon_budget[job_dag], critical_path_ratio

    def _update_carbon_budget(self, job_dag, current_carbon, exec_used, duration=1):
        if job_dag in self.job_carbon_budget:
            carbon_cost = current_carbon * exec_used * duration
            self.job_carbon_budget[job_dag] -= carbon_cost
            if self.job_carbon_budget[job_dag] < 0:
                self.job_carbon_budget[job_dag] = 0

    def _calculate_job_priority(self, job_dag, current_time, current_carbon, frontier_nodes):
        remaining, budget, critical = self._compute_job_metrics(job_dag, frontier_nodes)

        budget_ratio = 0.0
        if self.job_remaining_work[job_dag] > 0:
            budget_ratio = budget / (self.job_remaining_work[job_dag] * 300)

        time_to_low = float('inf')
        low_window_score = 0.0
        for t, data in self.carbon_forecast.items():
            if t >= current_time and data['in_low_window']:
                time_to_low = t - current_time
                low_window_score = -data['score']
                break

        alignment = 0.0
        if time_to_low < 100000:
            alignment = 1.0 - (time_to_low / 100000.0)

        priority = (
            0.6 * (remaining / max(1, self.job_remaining_work[job_dag])) +
            0.3 * critical -
            0.4 * budget_ratio +
            0.3 * alignment
        )

        if current_carbon > self.high_window_threshold and budget_ratio < 0.2:
            priority -= 1.0

        return priority

    def _adjust_capacity(self, current_time, current_carbon):
        self._update_carbon_forecast(current_time)

        if not self.carbon_forecast:
            self.exec_cap = self.exec_cap_MAX
            return

        now_data = None
        for t, data in sorted(self.carbon_forecast.items()):
            if t >= current_time:
                now_data = data
                break
        if not now_data:
            now_data = list(self.carbon_forecast.values())[-1]

        base = self.exec_cap_MAX
        multiplier = 1.0

        if now_data['carbon'] > self.high_window_threshold:
            gradient_factor = 1.0 + now_data['gradient'] / 100.0
            multiplier *= max(0.3, 1.0 / gradient_factor)

            time_to_low = float('inf')
            for t, data in self.carbon_forecast.items():
                if t > current_time and data['in_low_window']:
                    time_to_low = t - current_time
                    break

            if time_to_low < 50000:
                multiplier *= max(0.2, time_to_low / 50000.0)

        elif now_data['carbon'] < self.low_window_threshold:
            backlog_factor = 1.0
            total_used = sum(self.exec_map.values())
            if total_used > 0:
                backlog_factor = min(2.0, 1.0 + (total_used / self.exec_cap_MAX))
            multiplier *= backlog_factor

            if now_data['gradient'] < -10:
                multiplier *= 1.2

        else:
            if now_data['gradient'] < 0:
                multiplier *= 1.1
            elif now_data['gradient'] > 0:
                multiplier *= 0.9

        new_cap = int(base * multiplier)
        new_cap = max(self.B, min(self.exec_cap_MAX, new_cap))

        smooth_factor = 0.3
        self.exec_cap = int(smooth_factor * new_cap + (1 - smooth_factor) * self.exec_cap)
        self.exec_cap = max(self.B, min(self.exec_cap_MAX, self.exec_cap))

    def get_action(self, obs):
        job_dags, source_job, num_source_exec, frontier_nodes, executor_limits, exec_commit, moving_executors, action_map, current_time = obs

        for job_dag in job_dags:
            if job_dag not in self.exec_map:
                self.exec_map[job_dag] = 0
        for job_dag in list(self.exec_map):
            if job_dag not in job_dags:
                del self.exec_map[job_dag]
                if job_dag in self.job_slack:
                    del self.job_slack[job_dag]
                if job_dag in self.job_carbon_budget:
                    del self.job_carbon_budget[job_dag]
                if job_dag in self.job_remaining_work:
                    del self.job_remaining_work[job_dag]

        current_carbon, L, U = self.get_carbon_intensity(current_time)
        self._adjust_capacity(current_time, current_carbon)

        total_used = sum(self.exec_map.values())
        carbon_aware_pause = False

        if current_carbon >= U:
            low_window_soon = False
            for t, data in self.carbon_forecast.items():
                if t > current_time and t - current_time < 30000 and data['in_low_window']:
                    low_window_soon = True
                    break
            if low_window_soon and total_used > self.exec_cap * 0.7:
                carbon_aware_pause = True

        if total_used >= self.exec_cap or carbon_aware_pause:
            if source_job is not None and source_job in self.exec_map:
                self.exec_map[source_job] = max(self.exec_map[source_job] - num_source_exec, 0)
            return None, num_source_exec, True

        if source_job is not None:
            for node in frontier_nodes:
                if node.job_dag == source_job:
                    remaining = node.num_tasks - node.next_task_idx
                    commit = exec_commit.node_commit.get(node, 0)
                    moving = moving_executors.count(node)
                    available = remaining - commit - moving

                    if available <= 0:
                        continue

                    use_exec = min(available, num_source_exec, self.exec_cap - self.exec_map[source_job])

                    if use_exec > 0:
                        self.exec_map[source_job] += use_exec
                        carbon_aware_flag = (current_carbon >= U)
                        if carbon_aware_flag:
                            self._update_carbon_budget(source_job, current_carbon, use_exec)
                        return node, use_exec, carbon_aware_flag

        job_priorities = []
        for job_dag in job_dags:
            if self.exec_map[job_dag] >= self.exec_cap:
                continue

            priority = self._calculate_job_priority(job_dag, current_time, current_carbon, frontier_nodes)
            heapq.heappush(job_priorities, (-priority, job_dag))

        while job_priorities:
            _, job_dag = heapq.heappop(job_priorities)

            selected_node = None
            for node in frontier_nodes:
                if node.job_dag == job_dag:
                    selected_node = node
                    break

            if selected_node is None:
                continue

            remaining = selected_node.num_tasks - selected_node.next_task_idx
            commit = exec_commit.node_commit.get(selected_node, 0)
            moving = moving_executors.count(selected_node)
            available = remaining - commit - moving

            if available <= 0:
                continue

            max_for_job = self.exec_cap - self.exec_map[job_dag]
            use_exec = min(available, num_source_exec, max_for_job)

            if use_exec <= 0:
                continue

            node_slack = self.job_slack[job_dag].get(selected_node, 1)
            if current_carbon >= U and node_slack > 0:
                use_exec = max(1, int(use_exec * 0.3))

            self.exec_map[job_dag] += use_exec
            carbon_aware_flag = (current_carbon >= U) or (current_carbon > 350 and node_slack > 0)

            if carbon_aware_flag:
                self._update_carbon_budget(job_dag, current_carbon, use_exec)

            return selected_node, use_exec, carbon_aware_flag

        return None, num_source_exec, False
# === END CARBON-AWARE LOGIC ===

