import numpy as np
from agents.agent import Agent
import math
from collections import defaultdict
import random

class NewAgent(Agent):
    def __init__(self, exec_cap, carbon_schedule, exec_lower_bound=20):
        Agent.__init__(self)
        self.exec_map = {}
        self.carbon_schedule = carbon_schedule
        self.exec_cap_MAX = exec_cap
        self.exec_cap = exec_cap
        self.B = exec_lower_bound
        self.min_executors = 1
        self.max_executors = 4
        self.task_durations = {}
        self.carbon_price_history = []
        self.historical_patterns = defaultdict(list)
        self.job_carbon_budgets = {}
        self.job_carbon_used = defaultdict(float)
        self.job_start_times = {}
        self.last_price_update = 0
        self.price_factor = 1.0
        self.urgency_cache = {}
        self.slowed_tasks = set()
        self.catchup_tasks = set()

    def get_carbon_intensity(self, current_time):
        current_carbon = self.carbon_schedule.get(current_time, 300)
        times = sorted(self.carbon_schedule.keys())
        future_times = [t for t in times if t > current_time and t <= current_time + 86400000]
        if len(future_times) >= 10:
            future_carbons = [self.carbon_schedule[t] for t in future_times]
            L = float(np.percentile(future_carbons, 10))
            U = float(np.percentile(future_carbons, 90))
            if L >= U:
                L = U - 10
        else:
            L = current_carbon * 0.7
            U = current_carbon * 1.3
            if L >= U:
                L = U - 10
        return current_carbon, L, U

    def _compute_carbon_price(self, current_time):
        times = sorted(self.carbon_schedule.keys())
        forecast_times = [t for t in times if t > current_time and t <= current_time + 86400000]
        if len(forecast_times) < 10:
            return 1.0

        current_carbon = self.carbon_schedule.get(current_time, 300)
        forecast_carbons = [self.carbon_schedule[t] for t in forecast_times]

        percentile = sum(1 for c in forecast_carbons if c < current_carbon) / len(forecast_carbons)

        if percentile <= 0.1:
            price = 0.3
        elif percentile <= 0.3:
            price = 0.5 + (percentile - 0.1) * 2.5
        elif percentile <= 0.7:
            price = 1.0 + (percentile - 0.3) * 1.25
        elif percentile <= 0.9:
            price = 1.5 + (percentile - 0.7) * 5.0
        else:
            price = 2.5 + (percentile - 0.9) * 5.0

        price = max(0.1, min(5.0, price))

        if self.carbon_price_history:
            smoothed = 0.7 * price + 0.3 * self.carbon_price_history[-1]
        else:
            smoothed = price

        self.carbon_price_history.append(smoothed)
        if len(self.carbon_price_history) > 100:
            self.carbon_price_history.pop(0)

        return smoothed

    def _compute_global_urgency(self, node, job_dag, current_time):
        key = (id(node), id(job_dag))
        if key in self.urgency_cache:
            cached_time, cached_urgency = self.urgency_cache[key]
            if current_time - cached_time < 5000:
                return cached_urgency

        if not hasattr(job_dag, 'frontier_nodes') or not job_dag.frontier_nodes:
            return 0.0

        total_tasks = node.num_tasks if hasattr(node, 'num_tasks') else 1
        current_depth = node.next_task_idx if hasattr(node, 'next_task_idx') else 0
        remaining_tasks = total_tasks - current_depth
        criticality = remaining_tasks / max(total_tasks, 1)

        if job_dag not in self.job_start_times:
            self.job_start_times[job_dag] = current_time
        elapsed_time = current_time - self.job_start_times[job_dag]
        expected_total_time = total_tasks * 15000
        time_pressure = min(elapsed_time / max(expected_total_time, 1), 2.0)

        if job_dag not in self.job_carbon_budgets:
            min_carbon = min(self.carbon_schedule.values()) if self.carbon_schedule else 300
            self.job_carbon_budgets[job_dag] = total_tasks * 15000 * min_carbon

        carbon_debt = self.job_carbon_used.get(job_dag, 0) / max(self.job_carbon_budgets[job_dag], 1)

        urgency = criticality * time_pressure / max(carbon_debt, 0.5)

        self.urgency_cache[key] = (current_time, urgency)
        if len(self.urgency_cache) > 1000:
            self.urgency_cache.pop(next(iter(self.urgency_cache)))

        return urgency

    def _estimate_task_duration(self, node):
        if node not in self.task_durations:
            self.task_durations[node] = 15000
        return self.task_durations[node]

    def _get_forecast_avg(self, current_time, horizon):
        times = sorted(self.carbon_schedule.keys())
        relevant_times = [t for t in times if t >= current_time and t <= current_time + horizon]
        if not relevant_times:
            return self.carbon_schedule.get(current_time, 300)
        values = [self.carbon_schedule[t] for t in relevant_times]
        return float(np.mean(values))

    def get_action(self, obs):
        job_dags, source_job, num_source_exec, frontier_nodes, executor_limits, exec_commit, moving_executors, action_map, current_time = obs

        for job_dag in job_dags:
            if job_dag not in self.exec_map:
                self.exec_map[job_dag] = 0
        for job_dag in list(self.exec_map):
            if job_dag not in job_dags:
                del self.exec_map[job_dag]

        if source_job is not None and source_job in self.exec_map:
            self.exec_map[source_job] = max(self.exec_map[source_job] - num_source_exec, 0)

        current_carbon, L, U = self.get_carbon_intensity(current_time)
        price_factor = self._compute_carbon_price(current_time)

        total_used_exec = sum(self.exec_map.values())
        available_global = self.exec_cap - total_used_exec

        if available_global <= 0 or num_source_exec <= 0:
            return None, num_source_exec, True

        candidate_tasks = []
        for node in frontier_nodes:
            job_dag = node.job_dag
            duration = self._estimate_task_duration(node)
            urgency = self._compute_global_urgency(node, job_dag, current_time)

            forecast_avg = self._get_forecast_avg(current_time, 3600000)
            carbon_cost = duration * current_carbon

            candidate_tasks.append((node, job_dag, urgency, carbon_cost, duration, forecast_avg))

        candidate_tasks.sort(key=lambda x: (-x[2], x[3]))

        allocated_this_round = 0
        selected_node = None
        use_exec = 0
        carbon_aware_flag = False

        for node, job_dag, urgency, carbon_cost, duration, forecast_avg in candidate_tasks:
            if allocated_this_round >= num_source_exec:
                break

            job_used = self.exec_map.get(job_dag, 0)
            available_for_job = min(available_global, self.exec_cap - job_used)
            if available_for_job <= 0:
                continue

            if price_factor > 1.5 and urgency < 0.3:
                if node in self.slowed_tasks:
                    base_alloc = self.min_executors
                else:
                    self.slowed_tasks.add(node)
                    base_alloc = self.min_executors
            elif price_factor < 0.8 and urgency > 0.7:
                if node in self.slowed_tasks:
                    self.slowed_tasks.discard(node)
                    self.catchup_tasks.add(node)
                base_alloc = min(self.max_executors, int(self.max_executors / max(price_factor, 0.1)))
            else:
                if node in self.slowed_tasks:
                    self.slowed_tasks.discard(node)
                base_alloc = max(self.min_executors, min(self.max_executors, int(self.max_executors / max(price_factor, 0.1))))

            alloc = min(base_alloc, num_source_exec - allocated_this_round, available_for_job)

            if alloc <= 0:
                alloc = self.min_executors
                alloc = min(alloc, num_source_exec - allocated_this_round, available_for_job)
                if alloc <= 0:
                    continue

            selected_node = node
            use_exec = alloc
            self.exec_map[job_dag] = job_used + alloc
            allocated_this_round += alloc
            carbon_aware_flag = True
            self.job_carbon_used[job_dag] += alloc * duration * current_carbon
            break

        if selected_node is None and candidate_tasks:
            for node, job_dag, urgency, carbon_cost, duration, forecast_avg in candidate_tasks:
                if allocated_this_round >= num_source_exec:
                    break
                job_used = self.exec_map.get(job_dag, 0)
                available_for_job = min(available_global, self.exec_cap - job_used)
                if available_for_job <= 0:
                    continue
                alloc = min(self.min_executors, num_source_exec - allocated_this_round, available_for_job)
                if alloc > 0:
                    selected_node = node
                    use_exec = alloc
                    self.exec_map[job_dag] = job_used + alloc
                    allocated_this_round += alloc
                    carbon_aware_flag = True
                    self.job_carbon_used[job_dag] += alloc * duration * current_carbon
                    break

        if selected_node is not None:
            return selected_node, use_exec, carbon_aware_flag
        return None, num_source_exec, False
# === END CARBON-AWARE LOGIC ===

