        self.job_carbon_budget = {}
        self.job_remaining_work = {}

        self.carbon_history = []
        self.history_window = 10

        self.low_window_threshold = 280
        self.high_window_threshold = 400

    def get_carbon_intensity(self, current_time):
        current_carbon = self.carbon_schedule.get(int(current_time), 300)
        L = self.low_window_threshold
        U = self.high_window_threshold
        return current_carbon, L, U

    def _update_carbon_forecast(self, current_time):
        if current_time - self.last_forecast_time < self.forecast_interval:
            return

        self.last_forecast_time = current_time
        self.carbon_forecast.clear()

        times = []
        carbons = []
        start_t = int(current_time)
        end_t = int(current_time) + self.forecast_horizon + 1
        for t in range(start_t, end_t, 10000):
            c = self.carbon_schedule.get(t, 300)
            times.append(t)
            carbons.append(c)

        if len(carbons) < 2:
            return

        window_size = 3
        ma = []
        for i in range(len(carbons)):
            start = max(0, i - window_size + 1)
            ma.append(np.mean(carbons[start:i+1]))

        gradient = np.gradient(ma)

        low_windows = []
        in_window = False
        window_start = 0
        for i, (t, c, m) in enumerate(zip(times, carbons, ma)):
            if c < self.low_window_threshold and m < self.low_window_threshold:
                if not in_window:
                    in_window = True
                    window_start = t
            else:
                if in_window:
                    low_windows.append((window_start, t))
                    in_window = False
        if in_window:
            low_windows.append((window_start, times[-1]))

        next_low_window = None
        for start, end in low_windows:
            if start > current_time:
                next_low_window = (start, end)
                break

        for i, t in enumerate(times):
            if i >= len(gradient):
                continue
            score = 0.0
            if carbons[i] < self.low_window_threshold:
                score = -2.0
            elif carbons[i] > self.high_window_threshold:
                score = 2.0
            else:
                score = (carbons[i] - 300) / 100

            if next_low_window:
                dist_to_start = max(0, next_low_window[0] - t) / 100000.0
                if t >= next_low_window[0] and t <= next_low_window[1]:
                    score -= 3.0
                elif t < next_low_window[0]:
                    score -= 1.0 / (1.0 + dist_to_start)

            self.carbon_forecast[t] = {
                'carbon': carbons[i],
                'score': score,
                'gradient': gradient[i],
                'in_low_window': carbons[i] < self.low_window_threshold
            }

    def _compute_job_metrics(self, job_dag, frontier_nodes):
        if job_dag not in self.job_remaining_work:
            total_tasks = 0
            for node in job_dag.nodes:
                total_tasks += node.num_tasks
            self.job_remaining_work[job_dag] = total_tasks

        remaining = 0
        for node in job_dag.nodes:
            remaining += node.num_tasks - node.next_task_idx

        if job_dag not in self.job_slack:
            self.job_slack[job_dag] = {}
            for node in job_dag.nodes:
                est = 0
                lst = float('inf')
                self.job_slack[job_dag][node] = max(0, lst - est)

        if job_dag not in self.job_carbon_budget:
            avg_low_carbon = 250
            self.job_carbon_budget[job_dag] = remaining * avg_low_carbon

        critical_path_ratio = 0.0
        for node in frontier_nodes:
            if node.job_dag == job_dag:
                if self.job_slack[job_dag].get(node, 1) == 0:
                    critical_path_ratio = 1.0
                    break

        return remaining, self.job_carbon_budget[job_dag], critical_path_ratio

