import numpy as np
from agents.agent import Agent
from collections import defaultdict, deque
import heapq

class NewAgent(Agent):
    def __init__(self, exec_cap, carbon_schedule, exec_lower_bound=20):
        Agent.__init__(self)
        self.exec_map = {}
        self.carbon_schedule = carbon_schedule
        self.exec_cap_MAX = exec_cap
        self.exec_cap = exec_cap
        self.B = exec_lower_bound

        self.idle_mode = False
        self.idle_duration_remaining = 0
        self.task_duration_cache = {}
        self.last_idle_time = -float('inf')
        self.idle_cooldown = 20000
        self.low_carbon_threshold_ratio = 0.3
        self.high_carbon_threshold_ratio = 0.7
        self.short_task_threshold = 5
        self._counter = 0

    def get_carbon_intensity(self, current_time):
        current_carbon = self.carbon_schedule.get(int(current_time), 300)
        L = 200
        U = 500
        return current_carbon, L, U

    def _estimate_task_duration(self, node):
        node_id = id(node)
        if node_id not in self.task_duration_cache:
            duration = max(1, node.num_tasks // 10)
            self.task_duration_cache[node_id] = duration
        return self.task_duration_cache[node_id]

    def _get_next_low_carbon_time(self, current_time, L, U):
        current_carbon = self.carbon_schedule.get(int(current_time), 300)
        if current_carbon < L + 0.3 * (U - L):
            return current_time
        look_ahead = 100000
        step = 10000
        for t in range(int(current_time) + step, int(current_time) + look_ahead + step, step):
            c = self.carbon_schedule.get(t, 300)
            if c < L + 0.3 * (U - L):
                return t
        return int(current_time) + look_ahead

    def get_action(self, obs):
        job_dags, source_job, num_source_exec, frontier_nodes, executor_limits, exec_commit, moving_executors, action_map, current_time = obs

        for job_dag in job_dags:
            if job_dag not in self.exec_map:
                self.exec_map[job_dag] = 0
        for job_dag in list(self.exec_map):
            if job_dag not in job_dags:
                del self.exec_map[job_dag]

        current_carbon, L, U = self.get_carbon_intensity(current_time)

        if current_carbon > U:
            normalized_carbon = min(1.0, (current_carbon - L) / (U - L))
        else:
            normalized_carbon = max(0.0, (current_carbon - L) / (U - L))

        if self.idle_mode:
            self.idle_duration_remaining -= 1
            if self.idle_duration_remaining <= 0:
                self.idle_mode = False
                self.last_idle_time = current_time
            else:
                if source_job is not None and source_job in self.exec_map:
                    self.exec_map[source_job] = max(self.exec_map[source_job] - num_source_exec, 0)
                return None, num_source_exec, True

        total_used = sum(self.exec_map.values())

        if current_time - self.last_idle_time > self.idle_cooldown:
            if normalized_carbon > self.high_carbon_threshold_ratio:
                backlog_ratio = len(frontier_nodes) / max(1, len(job_dags) * 5)
                if backlog_ratio < 0.5:
                    next_low = self._get_next_low_carbon_time(current_time, L, U)
                    time_to_low = max(0, next_low - current_time)
                    idle_duration = int(min(
                        (normalized_carbon - self.high_carbon_threshold_ratio) * 100,
                        time_to_low / 10000,
                        30
                    ))
                    if idle_duration > 3:
                        self.idle_mode = True
                        self.idle_duration_remaining = idle_duration
                        if source_job is not None and source_job in self.exec_map:
                            self.exec_map[source_job] = max(self.exec_map[source_job] - num_source_exec, 0)
                        return None, num_source_exec, True

        if normalized_carbon < self.low_carbon_threshold_ratio:
            capacity = self.exec_cap_MAX
        elif normalized_carbon > self.high_carbon_threshold_ratio:
            capacity = max(self.B, int(self.exec_cap_MAX * (1 - normalized_carbon)))
        else:
            capacity = int(self.exec_cap_MAX * (1 - normalized_carbon * 0.5))

        capacity = max(self.B, min(self.exec_cap_MAX, capacity))
        self.exec_cap = capacity

        if total_used >= self.exec_cap:
            if source_job is not None and source_job in self.exec_map:
                self.exec_map[source_job] = max(self.exec_map[source_job] - num_source_exec, 0)
            return None, num_source_exec, True

        if source_job is not None:
            for node in frontier_nodes:
                if node.job_dag == source_job:
                    remaining = node.num_tasks - node.next_task_idx
                    commit = exec_commit.node_commit.get(node, 0)
                    moving = moving_executors.count(node)
                    available = remaining - commit - moving
                    if available <= 0:
                        continue
                    use_exec = min(available, num_source_exec, self.exec_cap - self.exec_map[source_job])
                    if use_exec > 0:
                        self.exec_map[source_job] += use_exec
                        duration = self._estimate_task_duration(node)
                        carbon_aware_flag = (duration > self.short_task_threshold and normalized_carbon > 0.3)
                        return node, use_exec, carbon_aware_flag

        job_priorities = []
        for job_dag in job_dags:
            if self.exec_map[job_dag] >= self.exec_cap:
                continue
            priority = 0.0
            for node in frontier_nodes:
                if node.job_dag == job_dag:
                    duration = self._estimate_task_duration(node)
                    if duration < self.short_task_threshold:
                        priority = 100.0
                    elif normalized_carbon < self.low_carbon_threshold_ratio:
                        priority = 60.0 + (node.num_tasks - node.next_task_idx) / max(1, node.num_tasks) * 20.0
                    else:
                        time_factor = 1.0 - normalized_carbon
                        priority = time_factor * 40.0 + (1 - normalized_carbon) * 20.0
                        if duration < self.short_task_threshold:
                            priority += 30.0
                    break
            heapq.heappush(job_priorities, (-priority, self._counter, job_dag))
            self._counter += 1

        while job_priorities:
            _, _, job_dag = heapq.heappop(job_priorities)
            selected_node = None
            for node in frontier_nodes:
                if node.job_dag == job_dag:
                    selected_node = node
                    break
            if selected_node is None:
                continue

            remaining = selected_node.num_tasks - selected_node.next_task_idx
            commit = exec_commit.node_commit.get(selected_node, 0)
            moving = moving_executors.count(selected_node)
            available = remaining - commit - moving
            if available <= 0:
                continue

            max_for_job = self.exec_cap - self.exec_map[job_dag]
            use_exec = min(available, num_source_exec, max_for_job)
            if use_exec <= 0:
                continue

            duration = self._estimate_task_duration(selected_node)
            if normalized_carbon > self.high_carbon_threshold_ratio and duration >= self.short_task_threshold:
                use_exec = max(1, int(use_exec * 0.3))

            self.exec_map[job_dag] += use_exec
            carbon_aware_flag = (duration >= self.short_task_threshold and normalized_carbon > 0.3)
            return selected_node, use_exec, carbon_aware_flag

        return None, num_source_exec, False
# === END CARBON-AWARE LOGIC ===

